void AgentWebView::set_error_fallback_actions(const wxString& return_label,
                                              const wxString& manual_label,
                                              std::function<void()> on_return,
                                              std::function<void()> on_manual)
{
    m_on_error_return = std::move(on_return);
    m_on_error_manual = std::move(on_manual);
    m_return_button->SetLabel(return_label);
    m_manual_button->SetLabel(manual_label);
    m_return_button->Show(static_cast<bool>(m_on_error_return));
    m_manual_button->Show(static_cast<bool>(m_on_error_manual));
    m_error_panel->Layout();
}

wxString AgentWebView::diagnostics_text(const wxString& reason) const
{
    wxString text = reason;
    text += "\n\n";
    text += _L("This is an internal connection between the application and its Agent panel, not a network service.");
    text += "\n";
    text += wxString::Format("URL: %s", m_page_url.empty() ? wxString(agent_page_path().string()) : m_page_url);
    if (!m_last_load_error.empty())
        text += wxString::Format("\n%s: %s", _L("Last load error"), m_last_load_error);
    text += wxString::Format("\n%s: %llu %s / %llu %s", _L("Bridge traffic"),
                             static_cast<unsigned long long>(m_host->messages_sent()), _L("sent"),
                             static_cast<unsigned long long>(m_host->messages_received()), _L("received"));
    return text;
}

void AgentWebView::show_bridge_error(const wxString& reason)
{
    m_error_detail->SetLabel(diagnostics_text(reason));
    m_error_detail->Wrap(std::max(FromDIP(160), GetClientSize().GetWidth() - FromDIP(32)));
    if (m_webview != nullptr)
        m_webview->Hide();
    m_error_panel->Show();
    Layout();
}

void AgentWebView::enable_chat_model_choice(AppConfig* config)
{
    // A list arrives on Http's thread; CallAfter brings it to this window's
    // thread, and drops it if the window is gone by then.
    m_host->set_chat_model_source(Agent::make_chat_model_source(config, [this](std::function<void()> deliver) {
        CallAfter(std::move(deliver));
    }));
}

void AgentWebView::hide_bridge_error()
{
    if (!m_error_panel->IsShown())
        return;
    m_error_panel->Hide();
    if (m_webview != nullptr)
        m_webview->Show();
    Layout();
}

void AgentWebView::apply_appearance(bool dark)
{
    const ShellPalette& palette = m_theme.palette(dark);
    SetBackgroundColour(palette.surface_subtle);
    m_error_panel->SetBackgroundColour(palette.surface_subtle);
    style_label(*m_error_title, m_theme, TextRole::BodyBold, palette.text_primary);
    style_label(*m_error_detail, m_theme, TextRole::Label, palette.text_secondary);
    style_button(*m_retry_button, m_theme, palette, m_theme.metrics().button.compact);
    style_button(*m_return_button, m_theme, palette, m_theme.metrics().button.compact);
    style_button(*m_manual_button, m_theme, palette, m_theme.metrics().button.compact);
    m_host->set_appearance(dark);
    Refresh();
}

